def int_to_words(n: int) -> str:
    if n == 0:
        return "zero"

    ones = [
        "", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine",
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen",
        "seventeen", "eighteen", "nineteen"
    ]

    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    def convert_below_thousand(num: int) -> str:
        if num == 0:
            return ""
        parts = []
        if num >= 100:
            parts.append(ones[num // 100] + " hundred")
            num %= 100
        if num >= 20:
            parts.append(tens[num // 10] + ("-" + ones[num % 10] if num % 10 else ""))
        elif num > 0:
            parts.append(ones[num])
        return " ".join(parts)

    result = []

    if n >= 1_000_000:
        millions = n // 1_000_000
        result.append(convert_below_thousand(millions) + " million")
        n %= 1_000_000

    if n >= 1_000:
        thousands = n // 1_000
        result.append(convert_below_thousand(thousands) + " thousand")
        n %= 1_000

    if n > 0:
        result.append(convert_below_thousand(n))

    return " ".join(result)
